def write(name, text):
    target = ROOT / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text.strip() + '\n')

def terrain():
    paths = []
    for j in range(24):
        pts = [(x, 55+j*15 + 29*math.sin(x/83+j*.19)+17*math.cos(x/48+j*.27)) for x in range(-30, 580, 8)]
        paths.append('<path d="M'+' L'.join(f'{x},{y:.1f}' for x,y in pts)+'"/>')
    return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 470" fill="none"><defs><pattern id="grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" stroke="#3c5049" stroke-width=".5"/></pattern></defs><rect width="560" height="470" fill="#1d302b"/><rect width="560" height="470" fill="url(#grid)"/><g stroke="#829586" stroke-width=".8" opacity=".5">'''+''.join(paths)+'''</g><path d="M75 385C150 310 160 380 236 280S328 218 399 124" stroke="#f2b391" stroke-width="2" stroke-dasharray="5 7"/><path d="M290 157L216 310L427 268Z" fill="#da7850" fill-opacity=".13" stroke="#da7850" stroke-opacity=".6"/><g transform="translate(290 157) rotate(-25)" stroke="#faf6ee" stroke-width="2"><path d="M-22-22L22 22M22-22L-22 22"/><circle cx="-22" cy="-22" r="11"/><circle cx="22" cy="22" r="11"/><circle cx="22" cy="-22" r="11"/><circle cx="-22" cy="22" r="11"/><rect x="-8" y="-13" width="16" height="26" rx="4" fill="#1d302b"/></g><g stroke="#e8ab83" stroke-width="1.5"><path d="M324 286h-8v8M344 286h8v8M316 314v8h8M352 314v8h-8"/><circle cx="334" cy="304" r="3" fill="#e8ab83"/></g><g fill="#eee8d9" font-family="monospace" font-size="10" letter-spacing="1"><text x="28" y="31">FIELD NOTES / PERCEPTION</text><text x="28" y="441">CAMERA → GEOMETRY → WORLD</text><text x="354" y="310">TARGET</text><text x="399" y="100">FLIGHT PATH</text></g><g stroke="#e8ab83"><path d="M24 58v-8h8M536 58v-8h-8M24 412v8h8M536 412v8h-8"/></g></svg>'''

def pipeline():
    return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 360"><rect width="560" height="360" fill="#ece5d9"/><g fill="none" stroke="#b6afa2"><path d="M50 70H510M50 180H510M50 290H510" stroke-dasharray="3 6"/><path d="M130 110V250H430V110" stroke-width="2"/></g><g fill="#faf8f3" stroke="#bbb4a7"><rect x="50" y="67" width="160" height="80" rx="3"/><rect x="350" y="67" width="160" height="80" rx="3"/><rect x="200" y="220" width="160" height="80" rx="3"/></g><g fill="#283b33" font-family="monospace" font-size="13" text-anchor="middle"><text x="130" y="103">DATA + MODELS</text><text x="130" y="124" font-size="10">evaluation</text><text x="430" y="103">INFERENCE</text><text x="430" y="124" font-size="10">latency + throughput</text><text x="280" y="258">OBSERVE + ITERATE</text></g><path d="M210 107H350M340 100l10 7-10 7" stroke="#aa4a29" fill="none" stroke-width="2"/><circle cx="130" cy="250" r="5" fill="#aa4a29"/><circle cx="430" cy="250" r="5" fill="#aa4a29"/></svg>'''

def geometry():
    return '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 360"><rect width="560" height="360" fill="#e3e8de"/><g stroke="#aab7a3" stroke-width="1" fill="none"><path d="M0 290Q80 220 160 275T320 272T560 235M0 309Q80 240 160 294T320 291T560 254M0 328Q80 260 160 313T320 310T560 273M0 347Q80 280 160 332T320 329T560 292"/></g><path d="M155 67L345 280M155 67V280H345" stroke="#ab4e2f" stroke-width="2" stroke-dasharray="5 5"/><path d="M145 55h28v20h-28z" fill="#2e4539"/><circle cx="164" cy="65" r="4" fill="#f7f4ec"/><circle cx="345" cy="280" r="7" fill="#ab4e2f"/><path d="M323 259h44v42h-44z" stroke="#ab4e2f" fill="none"/><g fill="#2e4539" font-family="monospace" font-size="11"><text x="184" y="64">CAMERA POSE</text><text x="249" y="158">VIEWING RAY</text><text x="365" y="284">GROUND TARGET</text><text x="32" y="325">TERRAIN / DEM</text></g></svg>'''

def layout(title, description, body, path='index.html', active=''):
    canonical = ORIGIN + ('/' if path == 'index.html' else '/' + path)
    nav = ''.join(f'<a href="{href}"'+(' aria-current="page"' if label==active else '')+f'>{label}</a>' for label,href in [('Work','index.html#work'),('Research','research.html'),('Teaching','teaching.html'),('About','about.html')])
    structured = {'@context':'https://schema.org','@type':'Person','name':'Ali El Habchi','url':ORIGIN+'/','jobTitle':'Assistant Professor in AI and Software Engineering','affiliation':{'@type':'Organization','name':'ENIAD Berkane, Mohammed Premier University'},'sameAs':[LINKEDIN,'https://github.com/elhabchiali'],'knowsAbout':['Computer vision','UAV perception','Production machine learning','MLOps']}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Ali El Habchi</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="theme-color" content="#f6f3ec"><link rel="canonical" href="{canonical}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)} | Ali El Habchi"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{json.dumps(structured)}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="header wrap"><a class="brand" href="/" aria-label="Ali El Habchi, home"><span class="brand-mark" aria-hidden="true">a.</span><span>Ali El Habchi<span class="brand-sub">RESEARCH · ENGINEERING · TEACHING</span></span></a><nav aria-label="Main navigation">{nav}<a class="nav-contact" href="mailto:{EMAIL}">Let's talk <span aria-hidden="true">↗</span></a></nav></header><main id="main">{body}</main><footer class="footer wrap"><a class="brand" href="/">Ali El Habchi<span class="footer-label">Computer vision, grounded in practice.</span></a><div><a href="{LINKEDIN}">LinkedIn ↗</a><a href="https://github.com/elhabchiali">GitHub ↗</a><a href="mailto:{EMAIL}">Email ↗</a></div><p>© 2026 Ali El Habchi · Morocco</p></footer></body></html>'''

def paper_list():
    return '<div class="papers">'+''.join(f'<article class="paper"><span class="mono">{year}</span><div><h3><a href="{url}">{title}<span aria-hidden="true"> ↗</span></a></h3><p>{venue}</p></div></article>' for year,title,venue,url in PAPERS)+'</div>'

def section_head(kicker, title, text=''):
    return f'<div class="section-head"><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p class="muted">{text}</p>' if text else '')+'</div>'

def project_intro(num, category, title, desc, tags):
    return f'<section class="page-head wrap"><a class="back" href="/index.html#work">← Selected work</a><p class="eyebrow">{num} / {category}</p><h1>{title}</h1><p class="lede">{desc}</p><div class="tags">'+''.join(f'<span>{t}</span>' for t in tags)+'</div></section>'

def case_sections(items):
    return '<div class="case-body wrap">'+''.join(f'<section class="case-section"><h2>{title}</h2><div>{content}</div></section>' for title,content in items)+'</div>'

def build():
    write('assets/terrain.svg', terrain());write('assets/pipeline.svg',pipeline());write('assets/geometry.svg',geometry())
    write('assets/favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#223c31"/><text x="12" y="47" font-family="Georgia,serif" font-size="52" fill="#faf5e9">a.</text></svg>')
    cards = [('01','Research & embedded vision','Seeing the world. On board.','Detection, motion cues, and efficient inference for UAV perception.','uav-perception.html','terrain','UAV perception and camera footprint illustrated over terrain'),('02','Industry experience','Models that make it into production.','From multilingual NLP to evaluation, optimization, and deployment.','production-ml.html','pipeline','Schematic of model evaluation, inference and iteration'),('03','Research & geometry','From a pixel to a place.','Aerial target geolocation through camera pose and terrain geometry.','aerial-geolocation.html','geometry','Viewing ray from a camera intersecting a terrain model')]
    projects='<div class="project-grid">'+''.join(f'<article class="project"><a class="project-image" href="/{url}" tabindex="-1" aria-hidden="true"><img src="/assets/{asset}.svg" width="560" height="360" alt="" loading="lazy"></a><div class="project-meta mono">{num} / {category}</div><h3><a href="/{url}">{title}<span aria-hidden="true">↗</span></a></h3><p>{desc}</p><a class="text-link" href="/{url}">Explore the work <span aria-hidden="true">↗</span></a></article>' for num,category,title,desc,url,asset,alt in cards)+'</div>'
    home=f'''<section class="hero wrap"><div class="hero-text"><p class="eyebrow"><span class="dot"></span> COMPUTER VISION · APPLIED AI</p><h1>Teaching<br>machines<br>to <em>see.</em></h1><p class="lede">I'm Ali, an AI researcher, engineer, and educator connecting visual perception with systems that work in the real world.</p><div class="actions"><a class="button" href="#work">Explore my work <span aria-hidden="true">↗</span></a><a class="text-link" href="/ali-el-habchi-cv.pdf">Download CV ↓</a></div></div><figure class="hero-figure"><img src="/assets/terrain.svg" width="560" height="470" alt="Illustrated drone flight path, camera footprint and ground target over terrain contours"><figcaption><span class="mono">01 / THE WORLD THROUGH A CAMERA</span><span>Perception → understanding → action</span></figcaption></figure><div class="hero-foot"><span>Assistant Professor · ENIAD Berkane</span><span>PhD in Computer Science & AI</span><a href="#work">Scroll to explore ↓</a></div></section><section class="section wrap" id="work">{section_head('01 / SELECTED WORK','Ideas, built into systems.','A selection of research and engineering work across aerial perception, production ML, and geometry.')}{projects}</section><section class="lab-teaser"><div class="wrap lab-split"><div><p class="eyebrow">02 / A SMALL EXPERIMENT</p><h2>What does a<br>filter actually <em>see?</em></h2><p>Take an image apart. Change a kernel. Follow the calculation behind a single pixel.</p><a class="button button-light" href="/lab.html">Enter the vision lab <span aria-hidden="true">↗</span></a><p class="lab-caption">An interactive teaching experiment. Runs in your browser.</p></div><a class="kernel-art" href="/lab.html" aria-label="Explore the interactive convolution lab"><span class="mono">SOBEL / HORIZONTAL DERIVATIVE</span><div class="matrix">{''.join(f'<span>{n}</span>' for n in [-1,0,1,-2,0,2,-1,0,1])}</div><span class="mono">A SMALL MATRIX. A DIFFERENT PERSPECTIVE.</span></a></div></section><section class="section wrap"><div class="split-heading">{section_head('03 / RESEARCH','Questions worth<br>looking into.')}<div><p>My PhD explored UAV navigation through computer vision and deep learning. My interests include obstacle perception, depth and motion, aerial geolocation, and efficient deployment.</p><a class="text-link" href="/research.html">Research & publications ↗</a></div></div>{paper_list()}</section><section class="about-strip wrap"><img src="/assets/portrait.webp" width="220" height="270" alt="Ali El Habchi" loading="lazy"><div><p class="eyebrow">04 / BEYOND THE MODEL</p><h2>Research informs the engineering.<br>Practice informs the teaching.</h2><p>I teach AI and software engineering at ENIAD Berkane, drawing on hands-on work with embedded vision, production ML, and software systems.</p><a class="text-link" href="/about.html">A little more about me ↗</a></div></section><section class="contact-section wrap"><p class="eyebrow">05 / START A CONVERSATION</p><h2>Have a problem<br>worth <em>exploring?</em></h2><div><p>For research collaborations, applied AI projects, or a conversation about teaching computer vision.</p><a class="contact-email" href="mailto:{EMAIL}">{EMAIL} ↗</a></div></section>'''
    write('index.html',layout('Computer vision, from research to practice','Ali El Habchi, PhD. AI researcher, engineer and educator at ENIAD Berkane. UAV perception, production machine learning and computer vision.',home))
    research=f'''<section class="page-head wrap"><p class="eyebrow">RESEARCH / COMPUTER VISION</p><h1>Perception with<br>a sense of <em>place.</em></h1><p class="lede">Understanding the scene is only the beginning. How can a camera help an autonomous system navigate, locate a target, and operate within real constraints?</p></section><section class="section wrap research-intro"><div><p class="eyebrow">DOCTORAL RESEARCH · 2025</p><h2>UAV navigation through computer vision & deep learning.</h2><p>PhD in Computer Science and Artificial Intelligence, ENSA Oujda, Mohammed Premier University. My work connects obstacle perception, visual motion and depth cues, and aerial target geolocation.</p><a class="text-link" href="mailto:{EMAIL}?subject=Doctoral%20research">Ask about the research ↗</a></div><img src="/assets/geometry.svg" width="560" height="360" alt="Schematic viewing ray connecting a camera to a target on terrain"></section><section class="section wrap">{section_head('SELECTED PUBLICATIONS','Papers & collaborations.','Links below point to the publication records. Co-authored results belong to the full research team.')}{paper_list()}</section><section class="section wrap">{section_head('ONGOING INTERESTS','Where I’m looking next.')}<div class="interest-grid"><article><span class="mono">01</span><h3>Visual navigation</h3><p>Obstacle perception, motion-based depth, and reliable visual cues for drones and mobile robots.</p></article><article><span class="mono">02</span><h3>Efficient perception</h3><p>Models and inference pipelines designed with hardware, latency, and evaluation constraints in mind.</p></article><article><span class="mono">03</span><h3>Learning from stronger models</h3><p>Exploring how foundation models and multimodal representations can inform practical robotic perception.</p></article></div></section>'''
    write('research.html',layout('Research & publications','Selected research by Ali El Habchi on UAV perception, aerial geolocation and efficient computer vision.',research,'research.html','Research'))
    teaching='''<section class="page-head wrap"><p class="eyebrow">TEACHING / ENIAD BERKANE</p><h1>Make the abstract<br><em>tangible.</em></h1><p class="lede">I teach AI and software engineering through the connection between an idea, its implementation, and the choices that make it useful.</p></section><section class="section wrap"><div class="course-list"><article><span class="mono">01 / VISION ARTIFICIELLE</span><h2>From pixels to perception.</h2><p>Digital images, image formation and sensors, filtering, morphology, geometric transformations, feature extraction, and deep learning for vision.</p><a class="text-link" href="/lab.html">Try the image-filtering lab ↗</a></article><article><span class="mono">02 / DEVOPS & MLOPS</span><h2>From code and models to systems.</h2><p>Version control, reproducible environments, containers, CI/CD, deployment, monitoring, and the lifecycle of machine learning systems.</p></article><article><span class="mono">03 / SOFTWARE MODELLING</span><h2>Make the design explicit.</h2><p>Requirements, UML, structured data, and architecture: reasoning about a system before and during implementation.</p></article></div></section><section class="lab-teaser"><div class="wrap lab-split"><div><p class="eyebrow">OPEN EXPERIMENT</p><h2>Change a kernel.<br>See the <em>difference.</em></h2><p>A compact learning tool for inspecting image filtering and following the calculation behind one output pixel.</p><a class="button button-light" href="/lab.html">Open the vision lab ↗</a></div><div><h3>How I approach teaching</h3><p>Start with the problem. Explain the mechanism. Work through a small example. Then connect it to real software and the limits of the method.</p><p>For course-related questions or academic collaboration, <a href="mailto:elhabchiali@gmail.com">get in touch</a>.</p></div></div></section>'''
    write('teaching.html',layout('Teaching','Computer vision, DevOps, MLOps and software modelling teaching at ENIAD Berkane, with an interactive image-processing lab.',teaching,'teaching.html','Teaching'))
    about='''<section class="page-head wrap"><p class="eyebrow">ABOUT / ALI EL HABCHI</p><h1>A researcher’s curiosity.<br>An engineer’s <em>instinct.</em></h1><p class="lede">I work at the intersection of computer vision, applied machine learning, and software engineering. I care about both the idea and what happens when it meets real data, hardware, and users.</p></section><section class="section wrap bio"><img src="/assets/portrait.webp" width="360" height="440" alt="Portrait of Ali El Habchi"><div><p class="eyebrow">BASED IN MOROCCO</p><h2>Research, practice,<br>and the classroom.</h2><p>I am an Assistant Professor in AI and Software Engineering at ENIAD Berkane, Mohammed Premier University. I hold a PhD in Computer Science and AI from ENSA Oujda, completed in 2025.</p><p>My industry experience spans UAV computer vision at ATLAN Space and machine learning engineering at Onclusive and Onclusive Social. It includes model development, embedded inference, multilingual NLP, and deployment workflows.</p><p>In the classroom, I teach computer vision, DevOps/MLOps, and software modelling. My research interests remain rooted in perception and autonomous systems.</p><a class="button" href="/ali-el-habchi-cv.pdf">Download my CV ↓</a></div></section><section class="section wrap">'''+section_head('EXPERIENCE','A path across disciplines.')+'''<div class="timeline"><article><span class="mono">OCT 2025 – PRESENT</span><div><h3>Assistant Professor · ENIAD Berkane</h3><p>Teaching AI and software engineering, supervising student projects, and developing practical learning experiences in vision and MLOps.</p></div></article><article><span class="mono">MAY 2024 – SEP 2025</span><div><h3>Senior Machine Learning Engineer · Onclusive</h3><p>Multilingual NLP, model evaluation and migration, inference optimization, and AWS-based ML workflows.</p></div></article><article><span class="mono">OCT 2023 – MAY 2024</span><div><h3>Machine Learning Engineering · Onclusive Social</h3><p>Logo detection and classification, data workflows, and reproducible model delivery. Formerly Digimind.</p></div></article><article><span class="mono">AUG 2018 – SEP 2023</span><div><h3>Senior R&D / Computer Vision Engineer · ATLAN Space</h3><p>UAV perception, object detection, embedded deployment, depth cues, and target geolocation.</p></div></article></div></section><section class="section wrap">'''+section_head('TOOLS & PRACTICE','A toolkit, shaped by the problem.')+'''<div class="interest-grid"><article><h3>Perception & learning</h3><p>Python · PyTorch · TensorFlow · OpenCV · NumPy · Hugging Face</p></article><article><h3>Inference & delivery</h3><p>TensorRT · ONNX · Jetson · AWS · Docker · Kubernetes · MLflow</p></article><article><h3>Software & geometry</h3><p>C++ · Java · FastAPI · Git · OpenGL · Camera geometry</p></article></div></section>'''
    write('about.html',layout('About & experience','Ali El Habchi is an AI researcher, engineer and educator based in Morocco, with experience in UAV vision and production machine learning.',about,'about.html','About'))
    uav=project_intro('01','UAV PERCEPTION','Seeing the world.<br><em>On board.</em>','Computer vision is a different engineering problem when the model has to run on an aircraft. Accuracy matters, but so do latency, data quality, and the hardware carrying it.',['Computer vision','Embedded AI','UAVs'])
    uav+='<figure class="case-visual wrap"><img src="/assets/terrain.svg" width="560" height="470" alt="Conceptual illustration of a UAV camera footprint over terrain"><figcaption>Conceptual illustration of perception and camera coverage, not flight telemetry.</figcaption></figure>'
    uav+=case_sections([('The problem','<p>Small and distant targets, changing viewpoints, and constrained onboard compute make aerial perception challenging. A detector must be evaluated in the context of the camera stream and target hardware.</p>'),('My work','<p>At ATLAN Space, I worked on training and deploying detection and classification systems for obstacles, vehicles, people, boats, and other aerial applications. My work included OpenCV-based processing, TensorRT/ONNX inference, and deployment on Jetson Nano and Xavier AGX.</p><p>I also developed approaches using optical flow, clustering, and multi-view cues for obstacle perception and depth estimation. These themes informed my doctoral research.</p>'),('Engineering decisions','<ul><li>Evaluate quality and execution time together rather than selecting a model on accuracy alone.</li><li>Compare the exported runtime with the training implementation and inspect preprocessing differences.</li><li>Consider the full camera-to-output pipeline, including memory transfers and post-processing.</li><li>Inspect small targets and difficult scenes explicitly, beyond aggregate metrics.</li></ul>'),('A related publication','<p>I co-authored a study on evolutionary architecture search for boat detection in aerial imagery. The paper reports a 68% reduction in operations relative to its parent network, alongside improved mAP. That result is specific to the published study and its experimental setup.</p><p><a class="text-link" href="https://doi.org/10.1007/s11554-023-01332-5">Read the 2023 publication ↗</a></p>'),('Limits and lessons','<p>Throughput depends on the complete deployment setup. A benchmark on one device, resolution, or dataset does not establish performance in a new environment. Public summaries here describe my work without distributing employer datasets or implementation code.</p>')])
    write('uav-perception.html',layout('UAV perception & embedded vision','Computer vision engineering for UAVs: aerial detection, motion cues and embedded inference.',uav,'uav-perception.html','Work'))
    production=project_intro('02','PRODUCTION MACHINE LEARNING','Beyond the<br><em>notebook.</em>','Building a useful ML system means connecting data, models, evaluation, inference, and the software that surrounds them.',['NLP','Inference optimization','MLOps'])
    production+='<figure class="case-visual wrap"><img src="/assets/pipeline.svg" width="560" height="360" alt="Conceptual ML lifecycle from evaluation to inference and iteration"><figcaption>Conceptual workflow, not an internal company architecture.</figcaption></figure>'
    production+=case_sections([('The context','<p>My previous roles at Onclusive and Onclusive Social connected model development with production engineering. The work covered multilingual NLP as well as visual brand analysis.</p>'),('My contributions','<p>At Onclusive, I worked on sentiment analysis, named-entity recognition, topic detection, keyword extraction, clustering, and summarization workflows. My engineering work included transformer model migration, tokenization and chunking, inference optimization, and AWS-based pipelines.</p><p>At Onclusive Social, I worked on logo detection and classification using YOLOv5 and ResNet50V2, alongside dataset management and model-delivery workflows.</p>'),('The engineering questions','<ul><li>How does a model change affect quality across languages and input lengths?</li><li>Where is the actual latency: tokenization, inference, data movement, or downstream processing?</li><li>What changes when inference uses quantization or another execution target?</li><li>Can the data, model, and runtime configuration be traced and reproduced?</li></ul>'),('Tools in the work','<p>Python, Hugging Face, PyTorch, AWS, Docker, Kubernetes, DVC, MLflow, and GitLab CI. The tool choice follows the workload, deployment constraints, and the team’s operating environment.</p>'),('What I learned','<p>Measure the system around the model and keep evaluation connected to deployment decisions. Improvements to a runtime, a model, or a preprocessing step only become useful when they fit the complete workflow.</p>')])
    write('production-ml.html',layout('Production machine learning','Multilingual NLP, inference optimization and model-delivery experience at Onclusive and Onclusive Social.',production,'production-ml.html','Work'))
    geo=project_intro('03','AERIAL TARGET GEOLOCATION','From a pixel<br>to a <em>place.</em>','An object detector tells us where something is in an image. Geolocation asks a different question: where is it in the world?',['Camera geometry','Terrain modelling','OpenGL'])
    geo+='<figure class="case-visual wrap"><img src="/assets/geometry.svg" width="560" height="360" alt="Camera viewing ray intersecting a terrain model at a ground target"><figcaption>Schematic geometry; the CGA publication uses colour-encoded terrain coordinates.</figcaption></figure>'
    geo+=case_sections([('The research question','<p>Estimate a ground target’s world position from an aerial image, using the target’s image location, UAV position and altitude, camera attitude, and a model of the terrain.</p>'),('The published approach','<p>I am first author of the CGA paper presented at ICDS 2020. The collaborative work encodes world positions as colours in a rendered terrain model, then decodes the relevant location. It uses SRTM elevation data and an OpenGL-based 3D environment.</p><p><a class="text-link" href="https://doi.org/10.1109/ICDS50568.2020.9268749">Read the CGA publication ↗</a></p>'),('My implementation work','<p>I developed target-geolocation software using OpenGL in C++ and later ported the approach to Java with LWJGL. This work connected camera and terrain geometry with the practical software needed to obtain a target location.</p>'),('The assumptions that matter','<ul><li>Camera calibration and the relationship between camera and vehicle frames.</li><li>Position, altitude, and attitude estimates aligned with the captured frame.</li><li>Terrain resolution and the coordinate and altitude reference systems.</li><li>A visible target on the modelled ground surface.</li></ul>'),('Limits and interpretation','<p>A precise-looking coordinate is not proof of accuracy. Attitude error, elevation error, calibration, and target localization all affect the estimate. This page summarizes the method rather than claiming an independently validated error bound.</p><p>For methodological detail and evaluation, use the publication record.</p>')])
    write('aerial-geolocation.html',layout('Aerial target geolocation','CGA research and implementation work connecting image coordinates, camera pose and terrain models.',geo,'aerial-geolocation.html','Work'))
    lab='''<section class="page-head wrap lab-heading"><p class="eyebrow">VISION LAB / INTERACTIVE TEACHING EXPERIMENT</p><h1>A different way<br>to <em>see a pixel.</em></h1><p class="lede">Choose an image, change the filter, then inspect the calculation. This demo applies a 3 × 3 kernel to a grayscale image, using the cross-correlation convention common in image-processing libraries.</p></section><section class="wrap lab-workspace" aria-label="Image filtering laboratory"><div class="lab-controls"><label>Input image<select id="sample"><option value="scene">Synthetic aerial scene</option><option value="shapes">Geometric shapes</option><option value="gradient">Gradient & edges</option></select></label><label class="upload">Or use your image<input id="upload" type="file" accept="image/*"></label><label>Filter<select id="filter"><option value="sobel">Sobel X</option><option value="blur">Box blur</option><option value="sharpen">Sharpen</option><option value="identity">Identity</option></select></label><button class="button" id="reset" type="button">Reset experiment ↺</button></div><p class="small muted" id="image-note">Synthetic input, not drone footage. Uploaded images stay in this browser and are resized to 128 × 128 pixels.</p><div class="lab-panes"><article><div class="pane-label"><span class="mono">01 / INPUT</span><span>128 × 128 · grayscale</span></div><canvas id="input" width="128" height="128" role="img" aria-label="Input grayscale image"></canvas><p class="small">Choose a pixel with the controls below to inspect its neighbourhood.</p></article><article class="operator-pane"><div class="pane-label"><span class="mono">02 / OPERATOR</span><span>3 × 3 kernel</span></div><div id="kernel" class="matrix" aria-label="Filter coefficients"></div><p id="filter-description"></p></article><article><div class="pane-label"><span class="mono">03 / OUTPUT</span><span>clipped to 0–255</span></div><canvas id="output" width="128" height="128" role="img" aria-label="Filtered grayscale image"></canvas><p class="small">Signed filter responses are clipped for display. Raw values appear below.</p></article></div><div class="inspect-controls"><label>Pixel X <input id="pixel-x" type="range" min="1" max="126" value="64"><output id="x-value">64</output></label><label>Pixel Y <input id="pixel-y" type="range" min="1" max="126" value="64"><output id="y-value">64</output></label><button class="button button-outline" id="step" type="button">Step through calculation</button><button class="button button-outline" id="next" type="button">Next pixel →</button></div><div class="calculation"><div><p class="eyebrow">INPUT NEIGHBOURHOOD × KERNEL</p><div id="neighbours" class="matrix" aria-label="Selected input neighbourhood"></div></div><div class="calculation-text"><p id="calculation" class="mono" aria-live="polite"></p><p id="step-detail" aria-live="polite"></p><p class="small muted">Border handling: replicate the closest edge pixel. Box blur divides the sum by 9. Pixel controls inspect interior pixels.</p></div></div><noscript><p>This interactive lab needs JavaScript. The rest of the portfolio remains available without it.</p></noscript></section><section class="section wrap"><div class="split-heading"><h2>Small operations.<br>Visible consequences.</h2><p>Sobel X responds to changes along the horizontal axis, making vertical boundaries stand out. Box blur averages a neighbourhood. Sharpen increases local contrast. Try the same input with each filter, then compare the coefficients and output.</p></div><a class="text-link" href="/teaching.html">More about my teaching ↗</a></section><script src="/filter-core.js" defer></script><script src="/lab.js" defer></script>'''
    write('lab.html',layout('Interactive vision lab','Explore image filtering with a three-pane convolution lab: input image, kernel and output with a step-by-step pixel calculation.',lab,'lab.html','Teaching'))
    write('404.html',layout('Page not found','The requested page could not be found.','<section class="page-head wrap"><p class="eyebrow">404 / NOT FOUND</p><h1>A little out<br>of <em>frame.</em></h1><p class="lede">That page is no longer here.</p><a class="button" href="/">Return to the portfolio ↗</a></section>','404.html'))
    pages=['','research.html','teaching.html','about.html','lab.html','uav-perception.html','production-ml.html','aerial-geolocation.html']
    write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}/{p}</loc></url>' for p in pages)+'</urlset>')
    write('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml')

